        R := 0.7;
        include 'Figures\Scripts\Dodecahedron_Coordinates.inc';

        R2 := R * 0.71;

        D1 := Rsin * As;
        D2 := Rsin * R2 / R;
        D3 := D2 * 1.002;

        CutV := R * 0.785;
        CutE := R * 0.81;

        // Puck parameters
        RP := R2 * 0.07;
        RPuck := R2 * 0.295;
        for i := 0 to 9 do begin
            x1[i] := RP * cos(2 * Pi / 10 * i);
            y1[i] := RP * sin(2 * Pi / 10 * i) + RPuck;
        end;
        z1 := D2 * 1.001;

        // Gray circles
        RC := R * 0.14;
        Sc := 0.98;

